def encode(s):
    result = []
    i = 0
    while i < len(s):
        ch = s[i]
        j = i + 1
        while j < len(s) and s[j] == ch:
            j += 1
        result.append(ch)
        run_length = j - i
        if run_length > 1:
            result.append(str(run_length))
        i = j
    return ''.join(result)


def decode(s):
    result = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        start = i
        while i < len(s) and s[i].isdigit():
            i += 1
        run_length = int(s[start:i]) if i > start else 1
        result.append(ch * run_length)
    return ''.join(result)
